import { useEffect, useMemo, useState } from 'react'
import {
  Background,
  Controls,
  Handle,
  MarkerType,
  MiniMap,
  Position,
  ReactFlow,
  ReactFlowProvider,
  useNodesInitialized,
  useNodesState,
  useReactFlow,
  type Edge,
  type Node,
  type NodeProps,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import {
  api,
  type DaprComponent,
  type IntegrationDetail,
  type SystemInfo,
  type Topology,
  type TopologyReport,
} from '../api'
import { CreateDrawer, type SlotKind } from './CreateDrawer'
import {
  CloudIcon,
  CycleIcon,
  HardDriveIcon,
  HubIcon,
  InputIcon,
  MemoryIcon,
  OutputIcon,
  SyncAltIcon,
} from '../icons'
import { Combobox, type ComboOption } from './Combobox'
import { FlowDetail, type FlowSelection } from './FlowDetail'

interface Props {
  selected: string | null
  onSelect: (path: string) => void
  /** Resolved app theme; drives React Flow's chrome (controls, minimap, edges). */
  theme: 'light' | 'dark'
}

// Layout geometry. The layout is deterministic: components and the topics
// they publish/subscribe flow left-to-right by declared depth inside the
// system boundary, and external systems (via ports) sit outside it.
const NODE_W = 300
const NODE_H = 84
const COL_GAP = 28
const ROW_GAP = 28
const GROUP_HEADER = 44
const GROUP_PAD = 20
const INFRA_W = 200
const INFRA_H = 76
const EXT_W = 184
const EXT_H = 72
const EXT_GAP = 96
const EXT_VGAP = 24

const WORKSPACE_KEY = '__workspace__'

/** Which way data crosses the system boundary for a component. */
type DataFlow = 'in' | 'out' | 'both' | 'internal'

// Boundary direction by declared component kind, used only to pick the card's
// directional glyph — never to invent wiring; every edge on the canvas comes
// from the declared topology.
const KIND_DATA_FLOW: Record<string, DataFlow> = {
  extractor: 'in',
  loader: 'out',
  transactional: 'both',
  transactionalintegration: 'both',
  aggregator: 'internal',
}

// dataFlowFor resolves a component kind to its boundary direction, ignoring
// case and hyphens (the topology library kebab-cases kinds, e.g.
// "transactional-integration").
function dataFlowFor(kind: string): DataFlow | undefined {
  return KIND_DATA_FLOW[kind.toLowerCase().replace(/-/g, '')]
}

// Directional glyph per data flow; integrations with no known flow keep the
// generic chip icon rather than guessing a direction.
const DATA_FLOW_ICONS: Record<DataFlow, typeof MemoryIcon> = {
  in: InputIcon,
  out: OutputIcon,
  both: SyncAltIcon,
  internal: CycleIcon,
}

interface IntNodeData extends Record<string, unknown> {
  name: string
  template: string
  dataFlow?: DataFlow
  selected: boolean
  /** Cron expression badge for schedule-triggered components (declared topology only). */
  trigger?: string
  /** Scaffolded but not in the declared topology yet — rendered muted/dashed
   *  until `sys create` re-assembles the host and the topology is refreshed. */
  ghost?: boolean
}

interface SlotNodeData extends Record<string, unknown> {
  kind: SlotKind
}

interface GroupNodeData extends Record<string, unknown> {
  title: string
  count: number
}

interface ExtNodeData extends Record<string, unknown> {
  name: string
  type: string
  direction?: DaprComponent['direction']
  /** Declared port name — the inspector's join key to the topology's
   *  ports[] and messageDocs. */
  port?: string
}

interface TopicNodeData extends Record<string, unknown> {
  name: string
  /** Pub/sub component the topic lives on — with name, the inspector's join
   *  key into the topology's topics[]. */
  pubsub?: string
  /** Data entity carried on the topic, e.g. "RawProduct". */
  entity?: string
  /** Contract ref when the topic is a declared API (contract surface). */
  contract?: string
}

// systemKey identifies a system by its root directory, the one grouping key
// that stays unique when two directories declare the same system name (e.g. a
// copied system). Integrations scaffolded at the workspace root fall under a
// "Workspace" pseudo-system.
function systemKey(it: IntegrationDetail): string {
  return it.systemPath || WORKSPACE_KEY
}

function systemLabel(it: IntegrationDetail): string {
  return [it.domain, it.system].filter(Boolean).join(' / ') || 'Workspace'
}

// topologyFor picks the declared topology for a system: the record its host
// produced, which carries the system directory as its path. The Workspace
// pseudo-system maps to a record at the root ('.').
function topologyFor(key: string, topologies: Topology[]): Topology | undefined {
  const path = key === WORKSPACE_KEY ? '.' : key
  return topologies.find((t) => t.path === path)
}

export function FlowView({ selected, onSelect, theme }: Props) {
  const [graph, setGraph] = useState<IntegrationDetail[] | null>(null)
  const [systemList, setSystemList] = useState<SystemInfo[] | null>(null)
  const [report, setReport] = useState<TopologyReport | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [refreshing, setRefreshing] = useState(false)
  const [system, setSystem] = useState<string | null>(null)
  const [workspaceName, setWorkspaceName] = useState<string | null>(null)
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([])
  // What the inspector panel shows: a clicked topic or port node.
  const [inspect, setInspect] = useState<FlowSelection | null>(null)
  // A clicked placeholder slot: which block kind the create drawer offers.
  const [draft, setDraft] = useState<SlotKind | null>(null)
  // The banner's host re-assembly (sys update / sys create) in flight.
  const [syncing, setSyncing] = useState(false)
  const [syncError, setSyncError] = useState<string | null>(null)

  // A different system means different topics/ports — drop the inspector,
  // any half-open create drawer, and a stale sync error.
  useEffect(() => {
    setInspect(null)
    setDraft(null)
    setSyncError(null)
  }, [system])

  useEffect(() => {
    const fail = (e: unknown) => setError(e instanceof Error ? e.message : String(e))
    api.flow().then(setGraph).catch(fail)
    api.systems().then(setSystemList).catch(fail)
    // The workspace pseudo-system labels itself after the served folder;
    // a miss keeps the generic fallback rather than failing the view.
    api
      .health()
      .then((h) => setWorkspaceName(h.workspace || null))
      .catch(() => {})
    // The first topology fetch runs each host's graph verb (a dotnet build),
    // so this request can take a while — the loading state covers it.
    api.topologies().then(setReport).catch(fail)
  }, [])

  const refresh = () => {
    setRefreshing(true)
    api
      .refreshTopologies()
      .then(setReport)
      .catch((e: unknown) => setError(e instanceof Error ? e.message : String(e)))
      .finally(() => setRefreshing(false))
  }

  const topologies = useMemo(() => report?.topologies ?? [], [report])

  // The dropdown lists every system present, with an integration count. When
  // a declared topology covers a group its system name is the authoritative
  // label, overriding the folder-derived one. Systems that end up sharing a
  // label are qualified with their directory so the options stay tellable
  // apart — the underlying keys are always distinct.
  const systems = useMemo<ComboOption[]>(() => {
    if (!graph) return []
    const opts = new Map<string, ComboOption>()
    for (const it of graph) {
      const key = systemKey(it)
      const opt = opts.get(key) ?? { value: key, label: systemLabel(it), count: 0 }
      opt.count = (opt.count ?? 0) + 1
      opts.set(key, opt)
    }
    // Declared systems with no blocks yet (a host-only scaffold) still get an
    // option — they render as the empty slot skeleton, the create surface's
    // best onboarding moment.
    for (const s of systemList ?? []) {
      if (!opts.has(s.path)) opts.set(s.path, { value: s.path, label: s.name, count: 0 })
    }
    // A workspace with nothing in it at all still offers the workspace
    // pseudo-system, so the canvas opens as the fillable slot skeleton
    // instead of a dead end — the first block scaffolds at the root.
    if (opts.size === 0) {
      opts.set(WORKSPACE_KEY, { value: WORKSPACE_KEY, label: 'Workspace', count: 0 })
    }
    // The pseudo-system labels itself after the served folder; a topology
    // declared at the root (below) still overrides with its system name.
    const ws = opts.get(WORKSPACE_KEY)
    if (ws && workspaceName) ws.label = workspaceName
    for (const opt of opts.values()) {
      const t = topologyFor(opt.value, topologies)
      if (t) opt.label = t.system
    }
    const byLabel = new Map<string, ComboOption[]>()
    for (const opt of opts.values()) {
      byLabel.set(opt.label, [...(byLabel.get(opt.label) ?? []), opt])
    }
    for (const dup of byLabel.values()) {
      if (dup.length > 1) for (const opt of dup) opt.label = `${opt.label} (${opt.value})`
    }
    return [...opts.values()].sort((a, b) => a.label.localeCompare(b.label))
  }, [graph, systemList, topologies, workspaceName])

  // Default to the first system once data lands.
  useEffect(() => {
    if (system === null && systems.length > 0) setSystem(systems[0].value)
  }, [systems, system])

  const items = useMemo(
    () => (graph && system ? graph.filter((it) => systemKey(it) === system) : []),
    [graph, system],
  )

  // Only a declared topology contributes wiring — there is no inferred
  // fallback. A system without one still renders: a synthetic empty record
  // makes every scaffolded block a ghost and shows the slot skeleton, so a
  // brand-new system is a fillable shape instead of a dead end.
  const declared = useMemo(
    () => (system ? topologyFor(system, topologies) : undefined),
    [system, topologies],
  )
  const effective = useMemo<Topology | undefined>(() => {
    if (declared) return declared
    if (!system) return undefined
    const label = systems.find((o) => o.value === system)?.label ?? system
    return {
      path: system === WORKSPACE_KEY ? '.' : system,
      apiVersion: 'topology.intropy.io/v1',
      system: label,
    }
  }, [declared, system, systems])
  const built = useMemo(
    () =>
      effective
        ? buildDeclaredGraph(effective, items)
        : { nodes: [] as Node[], edges: [] as Edge[], ghosts: [] as IntegrationDetail[] },
    [effective, items],
  )
  useEffect(() => setNodes(built.nodes), [built, setNodes])

  // After a create, the new scaffold shows up as a ghost through the normal
  // join — the placeholder→ghost transition is a data refresh, not UI state.
  const handleCreated = () => {
    setDraft(null)
    api.flow().then(setGraph).catch((e: unknown) =>
      setError(e instanceof Error ? e.message : String(e)),
    )
  }

  const sysDir = system === WORKSPACE_KEY ? '.' : system
  const hasHost = (systemList ?? []).some((s) => s.path === sysDir)

  // Re-assemble the host (sys update, or sys create when the system has no
  // host yet), then refresh the topology so the ghosts turn into declared
  // nodes — the banner's one click that closes the create loop.
  const syncHost = () => {
    if (!sysDir) return
    setSyncing(true)
    setSyncError(null)
    api
      .syncSystem(sysDir)
      .then((resp) => {
        setSyncing(false)
        refresh()
        // The create branch writes a new host scaffold: pick it up so the
        // picker and the button label agree with the workspace again.
        api.systems().then(setSystemList).catch(() => {})
        if (resp.action === 'create' && resp.hostDir) {
          // A new host changes every sibling's systemPath (the group key),
          // so the stale flow data would leave a duplicate picker entry.
          // Re-fetch and follow the selection onto the host's system dir.
          api.flow().then(setGraph).catch(() => {})
          const slash = resp.hostDir.lastIndexOf('/')
          setSystem(slash >= 0 ? resp.hostDir.slice(0, slash) : '.')
        }
      })
      .catch((e: unknown) => {
        setSyncing(false)
        setSyncError(e instanceof Error ? e.message : String(e))
      })
  }

  // Reflect the shared selection without disturbing dragged positions.
  useEffect(() => {
    setNodes((ns) =>
      ns.map((n) =>
        n.type === 'integration'
          ? { ...n, data: { ...n.data, selected: n.id === selected } }
          : n,
      ),
    )
  }, [selected, setNodes])

  if (error) {
    return <div className="banner error">{error}</div>
  }
  if (!graph || report === null) {
    return <p className="empty">Loading… (building system hosts on first run)</p>
  }

  return (
    <div className="flow-view">
      <div className="flow-toolbar">
        <span className="flow-toolbar-label">System</span>
        <Combobox
          value={system}
          options={systems}
          onChange={setSystem}
          placeholder="Select a system…"
        />
        <button
          type="button"
          className="flow-refresh"
          onClick={refresh}
          disabled={refreshing}
          title="Re-run each system host's graph verb"
        >
          {refreshing ? 'Refreshing…' : 'Refresh topology'}
        </button>
      </div>
      {report.errors?.length ? (
        <div className="banner error">
          {report.errors.map((e) => (
            <div key={e}>{e}</div>
          ))}
        </div>
      ) : null}
      {effective && !declared && (
        <div className="banner hint">
          No declared topology for this system yet — its components render
          from their scaffold records until the host's graph verb declares
          them.
        </div>
      )}
      {built.ghosts.length > 0 && (
        <div className="banner hint">
          {built.ghosts.length === 1
            ? '1 scaffolded component is'
            : `${built.ghosts.length} scaffolded components are`}{' '}
          not in the declared topology yet.
          <button
            type="button"
            className="flow-refresh"
            onClick={syncHost}
            disabled={syncing || refreshing}
            title={
              hasHost
                ? 'Fold the new components into the system host (sys update), then refresh the topology'
                : 'Assemble a system host from the scaffolds (sys create), then refresh the topology'
            }
          >
            {syncing
              ? hasHost
                ? 'Updating host…'
                : 'Creating host…'
              : hasHost
                ? 'Update host & refresh'
                : 'Create host & refresh'}
          </button>
        </div>
      )}
      {syncError && <div className="banner error">{syncError}</div>}
      {effective ? (
        <div className="flow-canvas">
          <ReactFlowProvider>
            <FlowCanvas
              nodes={nodes}
              edges={built.edges}
              onNodesChange={onNodesChange}
              onSelect={onSelect}
              onInspect={(sel) => {
                setInspect(sel)
                if (sel) setDraft(null)
              }}
              onSlotClick={(kind) => {
                setDraft(kind)
                setInspect(null)
              }}
              fitSignal={system ?? ''}
              theme={theme}
            />
          </ReactFlowProvider>
          {inspect && declared && (
            <FlowDetail
              selection={inspect}
              topology={declared}
              onClose={() => setInspect(null)}
            />
          )}
          {draft && system && (
            <CreateDrawer
              kind={draft}
              systemPath={system === WORKSPACE_KEY ? '.' : system}
              systemLabel={systems.find((o) => o.value === system)?.label ?? system}
              onClose={() => setDraft(null)}
              onCreated={handleCreated}
            />
          )}
        </div>
      ) : (
        <p className="empty">Select a system.</p>
      )}
    </div>
  )
}

// FlowCanvas hosts the React Flow instance so it can refit the viewport once
// nodes are measured, and again whenever the selected system changes — the
// `fitView` prop alone fits at init while the async node list is still empty.
function FlowCanvas({
  nodes,
  edges,
  onNodesChange,
  onSelect,
  onInspect,
  onSlotClick,
  fitSignal,
  theme,
}: {
  nodes: Node[]
  edges: Edge[]
  onNodesChange: Parameters<typeof ReactFlow>[0]['onNodesChange']
  onSelect: (path: string) => void
  onInspect: (selection: FlowSelection | null) => void
  onSlotClick: (kind: SlotKind) => void
  fitSignal: string
  theme: 'light' | 'dark'
}) {
  const rf = useReactFlow()
  const initialized = useNodesInitialized()

  useEffect(() => {
    if (initialized) rf.fitView({ padding: 0.2 })
  }, [initialized, fitSignal, rf])

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      onNodesChange={onNodesChange}
      nodeTypes={NODE_TYPES}
      colorMode={theme}
      minZoom={0.3}
      proOptions={{ hideAttribution: true }}
      onNodeClick={(_, node) => {
        if (node.type === 'integration') onSelect(node.id)
        if (node.type === 'topic') {
          const d = node.data as TopicNodeData
          if (d.pubsub) onInspect({ kind: 'topic', pubsub: d.pubsub, topic: d.name })
        }
        if (node.type === 'external') {
          const d = node.data as ExtNodeData
          if (d.port) onInspect({ kind: 'port', name: d.port })
        }
        if (node.type === 'slot') {
          onSlotClick((node.data as SlotNodeData).kind)
        }
      }}
      onPaneClick={() => onInspect(null)}
    >
      <Background gap={20} />
      <Controls showInteractive={false} />
      <MiniMap pannable zoomable />
    </ReactFlow>
  )
}


// refName extracts the display name from an entity ref: "component:pim-extractor"
// → "pim-extractor", "system:default/pim" → "pim".
function refName(ref: string): string {
  const rest = ref.slice(ref.indexOf(':') + 1)
  const slash = rest.lastIndexOf('/')
  return slash >= 0 ? rest.slice(slash + 1) : rest
}

// buildDeclaredGraph renders a system's declared topology (v1): components and
// the topics they publish/subscribe laid out left-to-right by flow depth
// inside the boundary, external systems (via ports) outside it. Nothing
// here is inferred — every node and edge comes straight from the record's
// inline wiring.
function buildDeclaredGraph(
  topo: Topology,
  items: IntegrationDetail[],
): { nodes: Node[]; edges: Edge[]; ghosts: IntegrationDetail[] } {
  const comps = topo.components ?? []

  // Metadata lookups: topics carry the contract, ports the external
  // system a component's inline reference resolves against.
  const topicMeta = new Map(
    (topo.topics ?? []).map((t) => [`${t.pubsub}/${t.topic}`, t]),
  )
  const portMeta = new Map((topo.ports ?? []).map((c) => [c.name, c]))

  // A topic node is identified by its (pubsub, topic) pair; a component by ref.
  const topicId = (pubsub: string, topic: string): string => `topic:${pubsub}/${topic}`

  // Map component refs to integration paths (a component's directory is its
  // name relative to the system root) so clicking a declared node selects the
  // scaffolded integration when one exists.
  const joinProject = (base: string, project: string): string => {
    if (project === '.' || project === '') return base
    return base === '.' ? project : `${base}/${project}`
  }
  const nodeId = new Map<string, string>()
  for (const c of comps) {
    const path = joinProject(topo.path, c.name)
    const matched = items.some((it) => it.path === path) ? path : undefined
    nodeId.set(`component:${c.name}`, matched ?? `component:${c.name}`)
  }

  // Collect the unique topics the components reference, and the internal flow
  // edges (component ⇄ topic) that decide layout depth.
  const topicRefs = new Map<string, { pubsub: string; topic: string }>()
  const flowEdges: Array<{ from: string; to: string }> = []
  for (const c of comps) {
    const cref = `component:${c.name}`
    for (const p of c.publishes ?? []) {
      const tid = topicId(p.pubsub, p.topic)
      topicRefs.set(tid, { pubsub: p.pubsub, topic: p.topic })
      flowEdges.push({ from: cref, to: tid })
    }
    for (const s of c.subscribes ?? []) {
      const tid = topicId(s.pubsub, s.topic)
      topicRefs.set(tid, { pubsub: s.pubsub, topic: s.topic })
      flowEdges.push({ from: tid, to: cref })
    }
  }
  for (const tid of topicRefs.keys()) nodeId.set(tid, tid)

  // Longest-path layering over the internal flow edges decides each node's
  // column. Kahn-style relaxation; anything left by a cycle lands in column 0
  // rather than failing the render.
  const internal = new Set<string>([
    ...comps.map((c) => `component:${c.name}`),
    ...topicRefs.keys(),
  ])
  const succ = new Map<string, string[]>()
  const indeg = new Map<string, number>()
  for (const r of internal) {
    succ.set(r, [])
    indeg.set(r, 0)
  }
  for (const e of flowEdges) {
    if (!internal.has(e.from) || !internal.has(e.to)) continue
    succ.get(e.from)?.push(e.to)
    indeg.set(e.to, (indeg.get(e.to) ?? 0) + 1)
  }
  const depth = new Map<string, number>()
  const queue = [...internal].filter((r) => indeg.get(r) === 0)
  for (const r of queue) depth.set(r, 0)
  while (queue.length > 0) {
    const r = queue.shift()!
    for (const n of succ.get(r) ?? []) {
      depth.set(n, Math.max(depth.get(n) ?? 0, (depth.get(r) ?? 0) + 1))
      indeg.set(n, indeg.get(n)! - 1)
      if (indeg.get(n) === 0) queue.push(n)
    }
  }
  for (const r of internal) if (!depth.has(r)) depth.set(r, 0)

  const cols = Math.max(1, Math.max(...[...depth.values()], 0) + 1)
  // At least three columns, so the create slots always sit in their archetype
  // positions (in → process → out) even when the declared graph is narrower —
  // an empty system renders as the fillable three-slot skeleton.
  const effCols = Math.max(cols, 3)
  const extractorCol = 0
  const loaderCol = Math.max(2, cols - 1)
  const transactionalCol = Math.min(loaderCol - 1, Math.max(1, Math.round(loaderCol / 2)))
  const contentTop = GROUP_HEADER
  const groupWidth = GROUP_PAD * 2 + effCols * NODE_W + (effCols - 1) * COL_GAP
  const colX = (d: number) => GROUP_PAD + d * (NODE_W + COL_GAP)

  const nodes: Node[] = []
  const edges: Edge[] = []
  const groupId = 'system'
  const rowsInCol: number[] = new Array<number>(effCols).fill(0)
  const place = (d: number): { x: number; y: number; row: number } => {
    const row = rowsInCol[d]++
    return { x: colX(d), y: contentTop + row * (NODE_H + ROW_GAP), row }
  }

  // Component positions, keyed by ref, so externals can anchor to the
  // component they touch instead of the far edge of the canvas.
  const compPos = new Map<string, { x: number; y: number; col: number }>()
  for (const c of comps) {
    const ref = `component:${c.name}`
    const col = depth.get(ref) ?? 0
    const pos = place(col)
    compPos.set(ref, { x: pos.x, y: pos.y, col })
    nodes.push({
      id: nodeId.get(ref)!,
      type: 'integration',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      data: {
        name: c.name,
        template: c.kind,
        dataFlow: dataFlowFor(c.kind),
        selected: false,
      } satisfies IntNodeData,
    })
  }

  for (const [tid, ref] of topicRefs) {
    const pos = place(depth.get(tid) ?? 0)
    const meta = topicMeta.get(`${ref.pubsub}/${ref.topic}`)
    nodes.push({
      id: nodeId.get(tid)!,
      type: 'topic',
      parentId: groupId,
      extent: 'parent',
      // Topics are narrower than component cards; center them in the column.
      position: { x: pos.x + (NODE_W - INFRA_W) / 2, y: pos.y },
      style: { width: INFRA_W, height: INFRA_H },
      data: {
        name: ref.topic,
        pubsub: ref.pubsub,
        contract: meta?.contract,
      } satisfies TopicNodeData,
    })
  }

  // Scaffolded-but-undeclared components: blocks whose scaffold record lives
  // in this system but whose name the declared topology does not carry —
  // brand new (pre `sys create`) or renamed. They render as ghosts in their
  // block kind's column, wireless, until the host declares them.
  const declaredPaths = new Set(comps.map((c) => joinProject(topo.path, c.name)))
  const ghosts = items.filter((it) => !declaredPaths.has(it.path))
  for (const g of ghosts) {
    const flow = g.dataFlow ?? (g.blockKind ? dataFlowFor(g.blockKind) : undefined)
    const col = flow === 'in' ? extractorCol : flow === 'out' ? loaderCol : transactionalCol
    const pos = place(col)
    nodes.push({
      id: g.path,
      type: 'integration',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      data: {
        name: g.name,
        template: g.blockKind || g.template,
        dataFlow: flow,
        selected: false,
        ghost: true,
      } satisfies IntNodeData,
    })
  }

  // Placeholder slots — one per kind column, always last in their column.
  // Clicking one opens the create drawer pre-filtered to that block kind;
  // the slots are affordances, never part of the declared graph.
  const slotDefs: Array<{ kind: SlotKind; col: number }> = [
    { kind: 'extractor', col: extractorCol },
    { kind: 'transactional', col: transactionalCol },
    { kind: 'loader', col: loaderCol },
  ]
  for (const s of slotDefs) {
    const pos = place(s.col)
    nodes.push({
      id: `slot:${s.kind}`,
      type: 'slot',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      style: { width: NODE_W, height: NODE_H },
      draggable: false,
      selectable: false,
      data: { kind: s.kind } satisfies SlotNodeData,
    })
  }

  const maxRows = Math.max(1, ...rowsInCol)
  const groupHeight = contentTop + maxRows * (NODE_H + ROW_GAP) - ROW_GAP + GROUP_PAD
  nodes.unshift({
    id: groupId,
    type: 'group',
    position: { x: 0, y: 0 },
    data: { title: topo.system, count: comps.length + ghosts.length } satisfies GroupNodeData,
    style: { width: groupWidth, height: groupHeight },
    draggable: false,
    selectable: false,
  })

  // Topic publish/subscribe edges. A publish leaves the component's right
  // ('ext') handle for the topic; a subscribe leaves the topic's right ('out')
  // handle for the subscriber.
  for (const c of comps) {
    const cref = `component:${c.name}`
    const comp = nodeId.get(cref)!
    for (const p of c.publishes ?? []) {
      const target = nodeId.get(topicId(p.pubsub, p.topic))
      if (!target) continue
      edges.push({
        id: `e:pub:${c.name}:${p.pubsub}/${p.topic}`,
        source: comp,
        sourceHandle: 'ext',
        target,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
    }
    for (const s of c.subscribes ?? []) {
      const source = nodeId.get(topicId(s.pubsub, s.topic))
      if (!source) continue
      edges.push({
        id: `e:sub:${s.pubsub}/${s.topic}:${c.name}`,
        source,
        sourceHandle: 'out',
        target: comp,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
    }
  }

  // Externals sit outside the boundary: a source (input port) directly left
  // of its component, a destination (output port) on a rail off the
  // boundary's right edge, aligned with its component's row and bumped down
  // when rows collide. Sources flow in on the left, destinations out on the
  // right — the same in → process → out reading as the columns inside.
  const railX = groupWidth + EXT_GAP
  const railYs: number[] = []
  const railY = (want: number): number => {
    let y = want
    while (railYs.some((used) => Math.abs(used - y) < EXT_H + EXT_VGAP)) {
      y += EXT_H + EXT_VGAP
    }
    railYs.push(y)
    return y
  }
  const pushExternal = (id: string, data: ExtNodeData, x: number, y: number): void => {
    if (nodes.some((n) => n.id === id)) return
    nodes.push({
      id,
      type: 'external',
      position: { x, y },
      style: { width: EXT_W, height: EXT_H },
      data,
      draggable: true,
    })
  }

  for (const c of comps) {
    const cref = `component:${c.name}`
    const comp = nodeId.get(cref)!
    const anchor = compPos.get(cref)!
    for (const use of c.ports ?? []) {
      const port = portMeta.get(use.port)
      const isInput = use.direction === 'in'
      const extId = `ext:${use.port}`
      const data: ExtNodeData = {
        name: port?.externalSystem ? refName(port.externalSystem) : use.port,
        type: 'port',
        direction: isInput ? 'input' : undefined,
        port: use.port,
      }
      if (isInput) {
        pushExternal(extId, data, anchor.x - EXT_W - EXT_GAP, anchor.y)
        edges.push({
          id: `e:port:${c.name}:${use.port}`,
          source: extId,
          sourceHandle: 'out',
          target: comp,
          targetHandle: 'in',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      } else {
        pushExternal(extId, data, railX, railY(anchor.y))
        edges.push({
          id: `e:port:${c.name}:${use.port}`,
          source: comp,
          sourceHandle: 'ext',
          target: extId,
          targetHandle: 'in',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      }
    }
  }

  return { nodes, edges, ghosts }
}

function GroupNode({ data }: NodeProps) {
  const { title, count } = data as GroupNodeData
  return (
    <div className="rf-group">
      <div className="rf-group-title">
        <span>{title}</span>
        <span className="count">{count}</span>
      </div>
    </div>
  )
}

function IntegrationNode({ data }: NodeProps) {
  const { name, template, dataFlow, selected, trigger, ghost } = data as IntNodeData
  const Icon = dataFlow ? DATA_FLOW_ICONS[dataFlow] : MemoryIcon
  return (
    <div className={`rf-int${selected ? ' selected' : ''}${ghost ? ' ghost' : ''}`}>
      <div className="rf-int-head">
        <Icon className="rf-int-icon" aria-hidden />
        <span className="rf-int-name">{name}</span>
        {template && <span className="rf-int-tag">{template}</span>}
        {trigger && (
          <span className="rf-int-tag" title="schedule trigger">
            {trigger}
          </span>
        )}
        {ghost && (
          <span
            className="rf-int-tag ghost-tag"
            title="scaffolded, not in the declared topology yet"
          >
            scaffolded
          </span>
        )}
      </div>

      <Handle type="target" position={Position.Left} id="in" />
      <Handle type="source" position={Position.Bottom} id="infra" />
      <Handle type="source" position={Position.Right} id="ext" />
    </div>
  )
}

// SlotNode is a create placeholder: one per block-kind column, low-contrast
// until hovered. Clicking it opens the create drawer for that kind. It has no
// handles — a slot carries no wiring.
const SLOT_LABELS: Record<SlotKind, string> = {
  extractor: 'Extractor',
  transactional: 'Core block',
  loader: 'Loader',
}

function SlotNode({ data }: NodeProps) {
  const { kind } = data as SlotNodeData
  return (
    <div className="rf-slot">
      <span className="rf-slot-plus" aria-hidden>
        +
      </span>
      <div className="rf-slot-text">
        <span className="rf-slot-name">{SLOT_LABELS[kind]}</span>
        <span className="rf-slot-hint">scaffold a new block</span>
      </div>
    </div>
  )
}

// TopicNode is a declared pub/sub topic: the first-class hop between
// components a declared topology makes visible. Contract topics show their
// contract ref; internal ones their data entity. The node draws as a
// horizontal cylinder — the message-channel glyph — so a topic reads as
// infrastructure between components, never as another component card.
function TopicNode({ data }: NodeProps) {
  const { name, entity, contract } = data as TopicNodeData
  // Topic names share a long common prefix, so lead with the short entity and
  // keep the full topic/contract in a tooltip. Fall back to the name when a
  // topic declares no entity.
  const primary = entity ?? name
  const secondary = contract ?? name
  const tip = contract ? `${name}\n${contract}` : name
  return (
    <div className="rf-infra pubsub rf-topic-cyl" title={tip}>
      {/* Silhouette: a rectangle with both ends bulging as elliptical arcs;
          the extra arc is the near cap's seam, making the left end read as
          the visible face of the cylinder. */}
      <svg className="rf-cyl" viewBox="0 0 200 76" aria-hidden focusable="false">
        <path className="rf-cyl-body" d="M 12 3 H 188 A 9 35 0 0 1 188 73 H 12 A 9 35 0 0 1 12 3 Z" />
        <path className="rf-cyl-seam" d="M 12 3 A 9 35 0 0 1 12 73" />
      </svg>
      <Handle type="target" position={Position.Left} id="in" />
      <HubIcon className="rf-infra-icon" aria-hidden />
      <div className="rf-infra-text">
        <span className="rf-infra-name">{primary}</span>
        <span className="rf-infra-kind">{secondary}</span>
      </div>
      <Handle type="source" position={Position.Right} id="out" />
    </div>
  )
}

function ExternalNode({ data }: NodeProps) {
  const { name, type, direction } = data as ExtNodeData
  const isDisk = /localstorage|localfile|disk|file/i.test(type)
  const Icon = isDisk ? HardDriveIcon : CloudIcon
  const kind = direction === 'input' ? 'source' : isDisk ? 'disk' : 'external'
  return (
    <div className="rf-ext">
      <Handle type="target" position={Position.Left} id="in" />
      <Handle type="target" position={Position.Top} id="top" />
      <Handle type="source" position={Position.Right} id="out" />
      <Icon className="rf-ext-icon" aria-hidden />
      <div className="rf-ext-text">
        <span className="rf-ext-name">{name}</span>
        <span className="rf-ext-kind" title={type}>
          {kind}
        </span>
      </div>
    </div>
  )
}

const NODE_TYPES = {
  group: GroupNode,
  integration: IntegrationNode,
  external: ExternalNode,
  topic: TopicNode,
  slot: SlotNode,
}

// Types mirror the Go JSON contract served by `intropy dashboard`
// (internal/dashboard). Integration matches template.ScaffoldEntry;
// IntegrationDetail adds the best-effort on-disk enrichment.

/** A dependency another template rendered alongside this integration. */
export interface DependencyRecord {
  template: string
  /** Slash-separated directory relative to the component root. */
  dir: string
}

export interface Integration {
  path: string
  schemaVersion: number
  template: string
  owner: string
  repo: string
  version: string
  /** Which way data crosses the system boundary, declared by the template
   *  (intropy.dev/data-flow label) and recorded in scaffold.json. */
  dataFlow?: 'in' | 'out' | 'both' | 'internal'
  /** Topology block kind the template scaffolds (intropy.dev/block-kind
   *  label), e.g. "extractor" or "loader". */
  blockKind?: string
  /** Support-project role (intropy.dev/template-role label). Projects with a
   *  role (system-host, shared-library) are filtered out of the catalog by
   *  the server; the field only appears on records read elsewhere. */
  role?: string
  /** Sibling projects this integration's template rendered as dependencies. */
  dependsOn?: DependencyRecord[]
  values: Record<string, unknown>
  /** Directory carrying the .intropy record; the integration's display name. */
  name: string
  /** Parent directory of the integration; absent directly under the root. */
  system?: string
  /** Parent directory of the system; absent when the system sits at the root. */
  domain?: string
  /** Root-relative directory of the system ("." when rooted at the workspace).
   *  The unique system key — two directories can declare the same `system`
   *  name — and the join key to a declared Topology's `path`. */
  systemPath?: string
}

export interface FileDoc {
  name: string
  content: string
}

/** A parsed Dapr component. `category` decides where the flow canvas draws it:
 *  `pubsub`/`state` inside the system boundary, `binding` outside — as a
 *  source when `direction` is `input`, a sink otherwise. */
export interface DaprComponent {
  name: string
  type: string
  category: 'pubsub' | 'state' | 'binding' | 'other'
  /** Normalized `direction` metadata from the component spec. Absent when
   *  undeclared — treated as unknown (rendered as a sink), never inferred. */
  direction?: 'input' | 'output' | 'input,output'
  file: string
}

export interface IntegrationDetail extends Integration {
  agents?: FileDoc
  readme?: FileDoc
  components?: DaprComponent[]
  pipelineSteps?: string[]
}

export interface Health {
  status: string
  version: string
  /** The served root's directory name — labels the workspace pseudo-system. */
  workspace?: string
}

/** One declared system: the directory holding a system-host scaffold
 *  (root-relative, the same identifier space as Integration.systemPath) and
 *  the name the host declares. */
export interface SystemInfo {
  path: string
  name: string
}

/** The POST /api/systems/{path} payload: what the host sync did. "update"
 *  folded orphans into an existing host, "create" assembled a new one,
 *  "none" found nothing to add and wrote nothing. */
export interface SystemSyncResponse {
  action: 'update' | 'create' | 'none'
  hostDir?: string
  system?: string
  added?: string[]
  /** Declared components whose scaffold is gone — kept as declared. */
  kept?: string[]
  diagnostics?: string[]
}

// Deployment state (internal/deploy). The server obtains each record by running
// the `deploy status` command with a JSON writer and passing its result through
// unchanged, so everything below is that command's own output — including the
// prose in `summary` and `notes`, which must be rendered as served rather than
// re-derived from `environments`.

/** How one overlay pins one image. */
export interface ResultPin {
  image: string
  /** The digest this replaced. Only present on a deployment's own result. */
  previous?: string
  digest: string
  /** The tag the digest was resolved from, or the tag pinned instead of a
   *  digest. Empty when the digest came from a release manifest. */
  tag?: string
}

/** One environment's row of the deployment ladder. */
export interface EnvironmentStatus {
  environment: string
  appName: string
  overlayPath: string
  /** False means there is no readable overlay here; `reason` says why and
   *  everything below is empty. On its own it never means "not deployed". */
  onboarded: boolean
  reason?: string
  /** The version this environment runs. Absent when it was deployed from a
   *  commit rather than a release, in which case `sourceCommit` stands in. */
  release?: string
  sourceCommit?: string
  /** Every image the component declares, in declared order. `digest` is empty
   *  when the overlay pins a tag or nothing — `tag` says which. */
  pins?: ResultPin[]
  /** The GitOps commit that last changed this overlay, and when it landed.
   *  Both absent when the overlay path has no history. */
  revision?: string
  /** RFC 3339. */
  deployedAt?: string
  syncPolicy: 'auto' | 'manual' | string
  /** What ArgoCD reports. Absent when it could not be read — which says
   *  nothing at all about what the overlay pins. */
  syncStatus?: string
  healthStatus?: string
  syncedRevision?: string
  /** What ArgoCD observed running in the cluster, as opposed to what the
   *  overlay pins. Absent under the same rule as `syncStatus`: its absence
   *  says nothing about the overlay or the cluster. */
  liveImages?: string[]
  /** A committed overlay change ArgoCD has not applied. For a `manual`
   *  environment that is an unspent gate at rest, not a fault. */
  pending: boolean
}

export interface StatusResult {
  component: string
  domain: string
  system: string
  /** Declared kind. "shared" holds system-level manifests and no image, so its
   *  empty digests are by design rather than evidence of never deploying. */
  kind: 'service' | 'shared' | string
  /** In promotion order: the last entry is the furthest downstream. */
  environments: EnvironmentStatus[]
  /** Every onboarded environment pins the identical digest for every image —
   *  what makes "prod runs the bits staging tested" a fact. */
  consistent: boolean
  /** The command's own sentence about what the environments collectively run.
   *  Render as served: `consistent` is a bool and the interesting cases are
   *  not — "these run different bits" and "there is nothing to compare" are
   *  both false and mean very different things. */
  summary: string
  /** The command's qualifications: an environment that could not be read, one
   *  pinning a tag, one waiting on a sync gate. */
  notes?: string[]
  /** The promotion graph restricted to this component's environments: for each
   *  environment, the ones a promotion into it may draw from. Carried on the
   *  result because deploy.yaml lives in the GitOps repository, which a
   *  consumer without a session cannot read. */
  promotesFrom?: Record<string, string[]>
}

// Catalog entry (internal/dashboard/catalog.go). Header identity and contracts
// come from the cached system topology when it has the component, and from the
// scaffold record — provenance only, it can go stale — otherwise. Deployment
// state is deliberately not embedded; it stays on /api/deploy/{path}, which
// costs a GitOps checkout refresh.

/** One end of a pub/sub wire a component sits on. */
export interface ContractEdge {
  pubsub: string
  topic: string
  /** The topic's contract shortName when the registry carries it, the raw
   *  contract name otherwise — the flow view's lookup rule. */
  contract?: string
  /** Every component the topic declares on each end of the wire — a contract
   *  shown as the connection between components, not a name. */
  publishers?: string[]
  subscribers?: string[]
}
/** One finding about the integration's place in the system graph. */
export interface CatalogCheck {
  severity: 'warn' | 'info'
  message: string
}

/** Why contracts are unknown, when they are: the catalog's join of the
 *  integration against its system's declared graph. */
export type GraphStatus =
  | 'matched'
  | 'no-topology'
  | 'not-in-graph'
  | 'topology-error'
  | 'pending'

export interface CatalogEntry {
  /** Graph name when matched, scaffold record name otherwise. */
  component: string
  /** Topology block kind; absent in every non-matched state. */
  kind?: string
  system?: string
  /** System directory the topology record joins on — for matching the
   *  contract registry when fetching /api/topology. */
  systemPath?: string
  publishes?: ContractEdge[]
  subscribes?: ContractEdge[]
  /** "owner/repo" from the scaffold record — provenance only. */
  repository?: string
  graphStatus: GraphStatus
  /** True while the first topology computation is in flight: the header
   *  renders from scaffold data and contracts are unknown. */
  topologyPending?: boolean
  /** Graph-derived findings, warns before infos. */
  checks?: CatalogCheck[]
}

/** The /api/deploy/{path} payload: what the deploy status command said about one
 *  integration, or why it could not say anything. */
export interface DeployState {
  status?: StatusResult
  /** The command's message, verbatim — an unconfigured GitOps repository, a
   *  component name matching several, a checkout another deploy is holding.
   *  None of these is a statement about the integration; only `status` is. */
  error?: string
  /** What the command wrote to stderr: which repository it refreshed, and any
   *  environment ArgoCD could not be read for. Provenance, not failure. */
  diagnostics?: string[]
  /** RFC 3339 — when the command ran. */
  readAt: string
}

// Declared system topology (internal/topology). The server obtains each
// record by running the system host's `graph` verb (apiVersion
// topology.intropy.io/v1) and caches the result until an explicit refresh.
// Wiring is inlined on each component — the topics it subscribes to and
// publishes on and the ports it uses — while the top-level `topics` and
// `ports` sections are the lookup tables those inline references resolve
// against. There is no fallback: a system whose host cannot produce a record
// appears in `errors` instead of `topologies`.

/** A component's subscription to a pub/sub topic. */
export interface TopicRef {
  pubsub: string
  topic: string
}

/** A component's output onto a pub/sub topic. */
export interface Publication {
  pubsub: string
  topic: string
}

/** A component's use of an external port. */
export interface PortUse {
  port: string
  /** "in" (external → component) or "out" (component → external). */
  direction: 'in' | 'out'
}

export interface TopologyComponent {
  name: string
  /** Block type: extractor, loader, transactional-integration, … */
  kind: string
  subscribes?: TopicRef[]
  publishes?: Publication[]
  ports?: PortUse[]
  /** Contract surfaces — parsed but not yet rendered (shape not finalized). */
  provides?: unknown[]
  consumes?: unknown[]
}

/** A declared pub/sub topic: metadata for a (pubsub, topic) pair components
 *  reference. */
export interface TopologyTopic {
  pubsub: string
  topic: string
  contract?: string
  publishers?: string[]
  subscribers?: string[]
}

/** An external system integration point. The name is its whole identity —
 *  the deployed Dapr binding type is environment-owned deployment
 *  configuration, never part of the record. */
export interface TopologyPort {
  name: string
  externalSystem?: string
  directions?: Array<'in' | 'out'>
  usedBy?: string[]
}

/** A message contract in the system's registry, keyed by `name` — the same
 *  fully-qualified type name TopologyTopic.contract references. */
export interface Contract {
  name: string
  /** "event" for pub/sub message contracts. */
  kind?: string
  /** Bare type name — the join key to a scaffold record's values.contract. */
  shortName?: string
  mediaType?: string
  /** Hash of the schema's canonical form; equal fingerprints mean equal
   *  shapes across systems. */
  fingerprint?: string
  /** JSON Schema as the host emitted it, passed through verbatim. */
  schema?: JsonSchema
}

/** The subset of JSON Schema the contract field tree renders. Anything it
 *  does not recognize falls back to a raw type label, never an error. */
export interface JsonSchema {
  type?: string | string[]
  format?: string
  properties?: Record<string, JsonSchema>
  required?: string[]
  items?: JsonSchema
  enum?: unknown[]
  $ref?: string
  $defs?: Record<string, JsonSchema>
}

/** One field or column of an external payload, as its author described it.
 *  `type` is loose by design — documentation, not a validatable schema. */
export interface MessageDocField {
  name: string
  position?: number
  type?: string
  required?: boolean
  notes?: string
}

/** A short inline payload excerpt. The server only serves samples whose
 *  author explicitly asserted the redaction check. */
export interface MessageDocSample {
  inline: string
  redacted?: boolean
}

/** An authored description of the payload a port carries (the flat file from
 *  an SFTP drop, the ad-hoc CSV export), read from the system's
 *  messages/<port>.md sidecar. Documentation, not enforcement. */
export interface MessageDoc {
  format?: string
  delimiter?: string
  encoding?: string
  filePattern?: string
  frequency?: string
  contact?: string
  lastReviewed?: string
  fields?: MessageDocField[]
  sample?: MessageDocSample
  /** Free prose from the doc's Markdown body. */
  body?: string
}

export interface Topology {
  /** Root-relative system directory, same identifier space as Integration.path. */
  path: string
  apiVersion: string
  kind?: string
  /** System name (a bare string in v1). */
  system: string
  components?: TopologyComponent[]
  topics?: TopologyTopic[]
  ports?: TopologyPort[]
  /** Message contract registry topics reference by contract name. Absent
   *  until the system host's topology library emits it. */
  contracts?: Contract[]
  /** Contract surfaces — parsed but not yet rendered (shape not finalized). */
  apis?: unknown[]
  /** Authored port payload descriptions, keyed by port name. CLI-merged
   *  enrichment from messages/<port>.md — not part of the host-declared
   *  topology, and re-read on every request. */
  messageDocs?: Record<string, MessageDoc>
}

/** The /api/topology payload: every declared topology plus the per-host
 *  failures (a host whose graph verb failed, e.g. because it pre-dates the
 *  verb or does not build). */
export interface TopologyReport {
  topologies: Topology[]
  errors?: string[]
}

async function requestJSON<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, init)
  if (!res.ok) {
    let message = `${res.status} ${res.statusText}`
    try {
      const body = (await res.json()) as { error?: string }
      if (body?.error) message = body.error
    } catch {
      // response had no JSON error body; keep the status line
    }
    // Carry the status so callers can branch on it — the create forms offer
    // force on a 409 (non-empty output directory).
    const err = new Error(message) as Error & { status?: number }
    err.status = res.status
    throw err
  }
  return (await res.json()) as T
}

const getJSON = <T,>(url: string) => requestJSON<T>(url)

export const api = {
  listIntegrations: () => getJSON<Integration[]>('/api/integrations'),
  getIntegration: (path: string) =>
    getJSON<IntegrationDetail>(`/api/integrations/${path}`),
  /** Every integration enriched with pipeline steps + Dapr components for the flow canvas. */
  flow: () => getJSON<IntegrationDetail[]>('/api/flow'),
  /** Every declared system — including hosts with no blocks yet, which
   *  /api/flow cannot surface (it only carries systems through their blocks). */
  systems: () => getJSON<SystemInfo[]>('/api/systems'),
  /** Re-assemble one system's host the way the CLI would: `sys update` when
   *  the directory has a host, `sys create` when it does not. Path "." is
   *  the workspace root. */
  syncSystem: (path: string, force = false) =>
    requestJSON<SystemSyncResponse>(`/api/systems/${path}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ force }),
    }),
  /** Every declared system topology, cached from the hosts' graph verbs. */
  topologies: () => getJSON<TopologyReport>('/api/topology'),
  /** Re-run every host's graph verb and return the fresh report. */
  refreshTopologies: () =>
    requestJSON<TopologyReport>('/api/topology/refresh', { method: 'POST' }),
  /** One integration's catalog entry: header facts and graph-derived checks. */
  catalog: (path: string) => getJSON<CatalogEntry>(`/api/catalog/${path}`),
  /** One integration's deployment state, read once and reused by the server. */
  deployState: (path: string) => getJSON<DeployState>(`/api/deploy/${path}`),
  /** Re-run `deploy status` for one integration and return the fresh result —
   *  how you pick up a deploy just made from another terminal. */
  refreshDeployState: (path: string) =>
    requestJSON<DeployState>(`/api/deploy/${path}`, { method: 'POST' }),
  health: () => getJSON<Health>('/api/health'),

